require_passing_json 'installed-check' '01-installed-check.cmd' 'installed recorder, Start-menu shortcut, and resources\\capture-helper.exe check' INSTALLED_JSON_OK
record_check START_SHORTCUT_OK "Did the automated installed check pass for the recorder and Start-menu shortcut?" "Reinstall or repair the selected destination, then rerun 01-installed-check.cmd."
record_check INSTALLED_HELPER_OK "Did the automated installed check find resources\\capture-helper.exe with the kit's expected SHA-256?" "Reinstall from the prepared installer and rerun 01-installed-check.cmd; do not substitute a manually copied helper."
step "In Hotkeys & options, click the Mark key button and press a connected controller/HID button. If no device is available, exercise the keyboard/log fallback and confirm the app log does not say capture-helper.exe not found."
record_check HID_FALLBACK_OK "Did a real controller/HID bind, or did the exercised fallback log avoid capture-helper.exe not found?" "Reconnect a device and retry binding, or exercise the fallback while watching the recorder log. Record failure if neither observation is available."
require_screenshot 'helper-hid' "the captured HID binding or the visible no-missing-helper log fallback" HELPER_SCREENSHOT_OK
pause "Bare-machine evidence is saved. Press Enter for the expected missing-pipeline negative check (stage 3); this negative result is not release completion."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Expected negative: pipeline command is missing before Python install"
say "This stage proves the packaged app fails clearly when its intentionally separate Python pipeline is absent. It cannot satisfy the release exit by itself."
step "Inside Sandbox, open read-only C:\\M5Kit and double-click 02-install-negative-fixture.cmd. It creates a valid Sessions-card fixture only for command resolution; collection explicitly rejects its ID."
pause "The helper says the negative-check fixture exists? Press Enter to continue in the installed recorder."
step "In Playtest Recorder, click Sessions → Refresh. On M5 expected missing-pipeline check only, click Run pipeline."
step "Read the app log. It must clearly include that playtest-pipeline is not recognized as a command, followed by Pipeline exited with code 1."
record_check MISSING_COMMAND_OK "Did the installed app log clearly report that playtest-pipeline was not recognized?" "Make sure Python and the pipeline have not yet been installed, refresh the fixture, rerun it from the Sessions card, and inspect the app log."
record_check MISSING_EXIT_OK "Did that same expected negative run end with Pipeline exited with code 1?" "Rerun the fixture from the Sessions card and keep the log visible through process exit. Do not accept the missing-command line without code 1."
require_screenshot 'missing-pipeline' "the recorder log showing both command-not-recognized and exit code 1" MISSING_PIPELINE_SCREENSHOT_OK
pause "Expected negative evidence is saved and explicitly not counted as completion. Press Enter to install release dependencies (stage 4)."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Release dependencies: official OBS 32, Python 3.11+, wheel, and preflight"
say "Use official browser downloads inside Sandbox. No account, credential, external FFmpeg download, purchase, or publishing action is needed."
step "Inside Sandbox File Explorer, double-click C:\\M5Kit\\OBS Studio 32.url. On the official OBS download page choose Windows and install OBS Studio major version 32. If the main button has moved to a newer major, use that official page's Previous Releases link and choose the newest official 32.x Windows installer; do not use a third-party download."
step "Double-click C:\\M5Kit\\Python 3.11+.url. On python.org choose the current Windows installer for Python 3.11 or newer, run it, select Add python.exe to PATH, and finish."
step "Open a new PowerShell inside Sandbox and run: py -3 --version"
step "In that same new PowerShell run: py -3 -m pip install \"C:\\M5Kit\\playtest_pipeline-0.1.0-py3-none-win_amd64.whl[all]\". The [all] metadata comes from the prepared wheel and installs its STT/VAD dependencies; FFmpeg and ffprobe still come only from that wheel."
step "Close Playtest Recorder completely, including its tray process, then launch it again from the Start menu so it inherits the newly installed pipeline command."
record_check OBS32_OK "Does OBS Help → About identify installed OBS Studio major version 32 from the official download?" "Return to the official OBS download page inside Sandbox and install the required major version; record failure if official version 32 cannot be installed."
record_check PYTHON_WHEEL_OK "Did py -3 report Python 3.11+ and did pip successfully install the prepared wheel with its [all] STT/VAD extras?" "Open a new PowerShell, correct the official Python PATH setup, rerun the exact wheel[all] install command, and observe success."
require_passing_json 'pipeline-tools-check' '03-pipeline-tools-check.cmd' 'pipeline CLI and selected-wheel-bundled FFmpeg/ffprobe without PATH' PIPELINE_TOOLS_JSON_OK
record_check BUNDLED_TOOLS_OK "Did 03-pipeline-tools-check.cmd pass with both tools resolving under playtest_pipeline\\bin while PATH was sanitized?" "Reinstall the prepared wheel, open a new PowerShell, and rerun the automated check. Do not install external FFmpeg or set PLAYTEST_FFMPEG_DIR."
step "Start OBS once. In the first-run Auto-Configuration Wizard choose Optimize just for recording, not streaming. Add a Display Capture source so the Sandbox desktop is recordable. The generated .wsb explicitly enables AudioInput, so microphone input is mandatory rather than optional."
step "OBS → Tools → WebSocket Server Settings → Enable WebSocket server. Do not copy or paste its password. Close OBS normally once so it saves its plugin config."
step "In Playtest Recorder click Setup wizard. Detect OBS, continue, start OBS when directed, connect, apply the recommended recording profile, restart OBS when directed, and continue through Face cam and Rig to Finish."
step "In OBS Advanced Audio Properties, keep desktop/game audio on track 1 and route the microphone to track 2. Speak continuously for several seconds while watching the OBS mixer; the microphone meter must visibly move before the live run is allowed."
record_check MICROPHONE_METER_OK "Did the routed microphone meter visibly move while you spoke, proving live audio input is present?" "Use OBS Settings → Audio to select the Sandbox microphone, verify host privacy/device access, and retry speaking. If no meter can move, record failure; do not claim or perform the mandatory dictated-note live run."
step "Back in the recorder, run preflight and correct actionable warnings; Sandbox hardware advisories may be recorded as limitations but must not be silently ignored."
record_check OBS_SETUP_OK "Did the recorder wizard complete with OBS websocket connection, recommended recording profile, and a reviewed preflight?" "Repeat the exact wizard/preflight path, restart OBS after applying settings, and correct or explicitly record every remaining warning."
require_screenshot 'obs-preflight' "the connected recorder with final preflight visible and the configured microphone mixer in context" OBS_PREFLIGHT_SCREENSHOT_OK
pause "Dependencies and OBS setup are captured. Press Enter for the required real recording and report observation (stage 5)."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Live exit run: real recording, mark/note, installed-app pipeline, and report"
say "This must be a real human-observed recording. The synthetic negative fixture cannot replace any step here. Keep Sandbox open through stage 6."
if [[ "$(state_answer MICROPHONE_METER_OK)" == yes ]]; then
step "In OBS, reconfirm Display Capture is visible and the required microphone meter moves. In Playtest Recorder enter a title beginning M5 Sandbox live, then Start recording."
step "Let it record for at least 10 seconds. Press the real Mark binding at least once and immediately dictate a short note; optionally press Issue and dictate another."
step "Use the Playtest Recorder tray icon to Stop. Reopen the recorder from the tray or Start menu and confirm the completed live session appears in Sessions."
record_check LIVE_DURATION_OK "Does the completed real session show a duration of at least 10 seconds?" "Record a new real session for longer than 10 seconds; do not edit timestamps or use the synthetic fixture."
record_check LIVE_MARK_OK "Did you make at least one real mark and dictate a note during that live recording?" "Record a new live session and use the actual configured mark input while recording, then speak immediately after it."
step "On that live session's Sessions card click Run pipeline. Keep the app open while the selected speech model downloads on first use and until the log reports exit code 0 and the session changes to Open report; no account or credential is required."
record_check LIVE_PIPELINE_OK "Did the pipeline run from the installed app, exit successfully, and emit Open report for the real session?" "Keep the recorder idle, rerun the pipeline from the live Sessions card, and correct any visible error."
require_screenshot 'live-pipeline' "the installed app's successful pipeline log and live session card" LIVE_PIPELINE_SCREENSHOT_OK
step "Click Open report. Play condensed.mp4 in the emitted report, locate the real note/mark row, click its timestamp, and compare the shown original time with the condensed playback position/content."
record_check REPORT_PLAYABLE_OK "Did the condensed video visibly play in the emitted report?" "Retry playback and the pipeline; record failure if the emitted condensed video is not playable."
record_check REPORT_NOTE_OK "Did the report show data corresponding to the real note/mark you made?" "Compare the live session's session.json marks with the report. Rerun the pipeline; do not use fixture data as a substitute."
record_check REPORT_TRANSCRIPT_OK "Did the real note row contain recognizable nonempty text transcribed from what you dictated?" "Confirm the wheel was installed with [all], the microphone was routed to track 2, speak clearly in a new live run, and rerun the pipeline; an empty mark label alone is not enough."
record_check REPORT_SEEK_OK "Did clicking the real note/mark timestamp seek to the marked content?" "Replay around the mark and retry the report link; record failure if seeking is wrong."
record_check REPORT_MAPPING_OK "Was the displayed original-to-condensed time mapping coherent with what you recorded and marked?" "Compare the report's original timestamp, condensed position, and visible recorded action; record failure rather than accepting an unexplained mismatch."
require_screenshot 'live-report' "the emitted report with playable video and the observed real note/mark/time mapping" LIVE_REPORT_SCREENSHOT_OK
step "Return to the live session card and use Folder to copy its full folder path. Inside Sandbox double-click C:\\M5Kit\\04-collect-live-evidence.cmd, paste that path when asked, and wait for copy plus hashes to finish."
step "The collector explicitly rejects m5-missing-pipeline-fixture; binds session.json to report_data.json by session ID/title/date and mark IDs/times; uses the selected wheel's bundled ffprobe for real source duration and condensed playability; and copies/hashes the source recording and report into C:\\M5Outbox."
require_passing_json 'collection' '04-collect-live-evidence.cmd' 'live session/report/source-media collection' COLLECTION_JSON_OK
else
  warn "The mandatory dictated-note run is blocked because no moving microphone meter was proven. Recording without live audio would create misleading evidence, so stage 5 is recorded as failed rather than allowed."
  for key in LIVE_DURATION_OK LIVE_MARK_OK LIVE_PIPELINE_OK REPORT_PLAYABLE_OK REPORT_NOTE_OK REPORT_TRANSCRIPT_OK REPORT_SEEK_OK REPORT_MAPPING_OK LIVE_PIPELINE_SCREENSHOT_OK LIVE_REPORT_SCREENSHOT_OK COLLECTION_JSON_OK; do write_env "$key" no; done
fi
say "Do not close Windows Sandbox. Stage 6 must validate the host-side mapped files first or record this attempt as failed."
pause "Live collection and all seven current-run screenshots are ready, or the live run was explicitly blocked? Press Enter for trusted host validation and the structured outcome (stage 6)."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Evidence: host validation, retry loop, and dated structured outcome"
say "The host now checks the mapped copies. Missing evidence triggers a retry; it is never silently accepted. Keep Windows Sandbox open until this validation passes or you deliberately record a failed run."
EVIDENCE_VALIDATED=no
while :; do
  say "The tracked repository helper first re-verifies its own pinned hash, the manifest hash, the read-only kit artifacts, MOTW, and bundled wheel entries before reading any outbox byte."
  if host_helper ValidateCopied; then EVIDENCE_VALIDATED=yes; break; fi
  warn "Trusted host validation rejected incomplete, stale, synthetic, tampered, unbound, undecodable, or wrong-run evidence. Read the failed check above and keep Sandbox open."
  reply=""
  printf '  %s? [r]etry after copying evidence / record this run as [f]ailed / [a]bort and resume later%s ' "$YELLOW" "$RESET"
  read -r reply || true
  case "$reply" in
    f|F) write_env COPIED_EVIDENCE_OK no; break ;;
    a|A) printf '  aborted — do not close Sandbox; re-run %s to resume.\n' "$RUN_COMMAND"; exit 1 ;;
    *) pause "Correct the mapped evidence while Sandbox remains open, then press Enter to validate again." ;;
  esac
done
if [[ "$EVIDENCE_VALIDATED" == yes ]]; then record_check COPIED_EVIDENCE_OK "Did trusted host-validation pass for strict guest JSON, seven decoded/hash-bound PNGs, bound live session/report/marks/notes, and ffprobe-verified source/condensed media?" "Keep Sandbox open, restore every missing mapped item, and rerun trusted host validation."; fi
ask_limitations
REQUIRED_KEYS=(SMARTSCREEN_REPUTATION_OK SMARTSCREEN_SCREENSHOT_OK INSTALL_DIR_OK START_SHORTCUT_OK FIRST_RUN_OK OBS_NOT_FOUND_OK INSTALLED_HELPER_OK HID_FALLBACK_OK MISSING_COMMAND_OK MISSING_EXIT_OK OBS32_OK PYTHON_WHEEL_OK BUNDLED_TOOLS_OK OBS_SETUP_OK MICROPHONE_METER_OK LIVE_DURATION_OK LIVE_MARK_OK LIVE_PIPELINE_OK REPORT_PLAYABLE_OK REPORT_NOTE_OK REPORT_TRANSCRIPT_OK REPORT_SEEK_OK REPORT_MAPPING_OK FIRST_RUN_SCREENSHOT_OK HELPER_SCREENSHOT_OK MISSING_PIPELINE_SCREENSHOT_OK OBS_PREFLIGHT_SCREENSHOT_OK LIVE_PIPELINE_SCREENSHOT_OK LIVE_REPORT_SCREENSHOT_OK INSTALLED_JSON_OK PIPELINE_TOOLS_JSON_OK COLLECTION_JSON_OK COPIED_EVIDENCE_OK)
FINAL_STATUS=PASS
for key in "${REQUIRED_KEYS[@]}"; do [[ "$(state_answer "$key")" == yes ]] || FINAL_STATUS=FAIL; done
OUTCOME_FILE="$(write_outcome "$FINAL_STATUS")"
say "${GREEN}✓${RESET} wrote the dated structured outcome without replacing an earlier outcome: $(to_win "$OUTCOME_FILE")"
if [[ "$FINAL_STATUS" == PASS ]]; then
  say "Every listed release-exit criterion and copied-evidence check passed for this Windows Sandbox run. This records the bounded M5 installer exit result; it does not declare the overall product milestone complete."
else
  warn "Outcome is FAIL because at least one required criterion was failed or missing. Keep the evidence and rerun the wizard after correction; it will preserve this outcome and create a new retry outcome."
fi
if [[ "$(state_answer COPIED_EVIDENCE_OK)" == yes ]]; then
  say "Host validation is complete. You may now close Windows Sandbox; anything needed for the record has been copied to the mapped host folder."
else
  warn "Copied evidence is incomplete. Do not close Windows Sandbox if you intend to recover this run; copy the missing files and rerun the wizard. Closing now means the failed outcome remains and guest-only evidence is lost."
fi
pause "Press Enter to show the wizard summary and exact saved outcome path."

if [[ "$FINAL_STATUS" == PASS ]]; then
  finish
  say "Outcome: $(to_win "$OUTCOME_FILE")"
  say "Run again with: $RUN_COMMAND"
else
  _clear
  printf '\n%s%s  ✗ Release exit recorded as FAIL%s\n\n' "$BOLD" "$RED" "$RESET"
  say "Outcome: $(to_win "$OUTCOME_FILE")"
  say "Correct the recorded failure, keep/copy any recoverable Sandbox evidence, then resume with: $RUN_COMMAND"
  exit 1
fi
